input.content:
plugins {
    id 'application'
    id 'java'
}

repositories {
    mavenCentral()
    mavenLocal()
}

dependencies {
    implementation 'com.badlogicgames.gdx:gdx:1.14.2'
    implementation 'com.badlogicgames.gdx:gdx-backend-headless:1.14.2'
    runtimeOnly 'com.badlogicgames.gdx:gdx-platform:1.14.2:natives-desktop'
}

application {
    mainClass = 'com.mygdx.astar.Main'
}

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(17)
    }
}

package com.mygdx.astar;

import com.badlogic.gdx.ApplicationAdapter;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;
import com.badlogic.gdx.utils.BinaryHeap;

public class Main extends ApplicationAdapter {
    private final String[] args;

    public Main(String[] args) {
        this.args = args;
    }

    @Override
    public void create() {
        try {
            System.out.println("Hello from libGDX Headless Application!");
            if (args.length > 0) {
                System.out.println("Arg 0: " + args[0]);
            }
        } finally {
            Gdx.app.exit();
        }
    }

    public static void main(String[] args) {
        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        new HeadlessApplication(new Main(args), config);
    }
}

package com.mygdx.astar;

import com.badlogic.gdx.ApplicationAdapter;
